SELECT e.account_code AS accountCode, MAX(e.account_name) AS accountName, SUM(CASE WHEN e.direction = 'DEBIT' THEN e.amount ELSE 0 END) AS debitAmount, SUM(CASE WHEN e.direction = 'CREDIT' THEN e.amount ELSE 0 END) AS creditAmount, SUM(CASE WHEN e.direction = 'DEBIT' THEN e.amount ELSE -e.amount END) AS balance FROM fin_voucher_entry e JOIN fin_voucher v ON v.voucher_id = e.voucher_id AND v.del_flag = '0' WHERE e.del_flag = '0' AND v.status IN ('AUDITED', 'POSTED')
AND e.period = #{period}
GROUP BY e.account_code ORDER BY e.account_code

